// server/services/environment-connectors/session/bound-session-evidence.ts
async function readBoundSessionEvidence(input, bindingStore) {
  if (input.context.profileId !== input.binding.profileRef || input.context.runId !== input.binding.runId || !input.binding.runId) {
    throw new TemporalPlanError("temporal_plan_task_context_mismatch");
  }
  await bindingStore.verifyTaskAssociation(input.binding);
  const context = await resolveTemporalPerceptionContext(input.context);
  const binding = await bindingStore.verifyTaskAssociation(input.binding);
  return {
    context,
    binding,
    execution_authority: false,
    answer_authority: false,
    terminal_eligible: false
  };
}

