async function readEnvironmentSessionReadiness(input, bindingStore, dependencies2 = readers) {
  if (input.context.profileId !== input.binding.profileRef || !input.context.runId || input.context.runId !== input.binding.runId) {
    throw new RoomEnvironmentSubjectError(
      "subject_binding_forbidden",
      403,
      "Session readiness requires an exact authenticated environment run."
    );
  }
  const room = { profileId: input.context.profileId, roomId: input.context.roomId };
  const membership = await dependencies2.membership(room);
  if (!membership || membership.participantId !== input.context.participantId || membership.roomStatus === "closed") {
    throw new RoomEnvironmentSubjectError(
      "subject_binding_forbidden",
      403,
      "Session readiness requires the current room participant."
    );
  }
  const binding = await bindingStore.verifyTaskAssociation(input.binding);
  const started = Date.now();
  const contextRef = `sha256:${(0, import_node_crypto35.createHash)("sha256").update(JSON.stringify([
    room.profileId,
    room.roomId,
    membership.participantId,
    input.binding.bindingId,
    input.binding.bindingEpoch,
    input.binding.helixConversationId,
    input.context.runId,
    input.context.goalId,
    input.context.expectedRevision,
    input.environmentBindingId,
    input.sourceId,
    input.worldId,
    input.subjectBindingId,
    input.actionAuthorityId
  ])).digest("hex")}`;
  const checks = [];
  const add = (layer, state, evidenceRef2, reasons = [], deadline = null, humanApprovalRequired = false) => {
    checks.push({
      layer,
      state,
      context_ref: contextRef,
      evidence_ref: evidenceRef2,
      observed_at_ms: started,
      expires_at_ms: deadline,
      reason_codes: reasons,
      // Diagnostic failure alone is not evidence that another consent is needed.
      human_approval_required: humanApprovalRequired
    });
  };
  const failure = (layer, error) => {
    const code = error instanceof RoomEnvironmentSubjectError || isEnvironmentActionAuthorityError(error) || isEnvironmentDurableGoalError(error) ? error.code : "session_check_unavailable";
    add(layer, "blocked", `session_check:${layer}`, [code]);
  };
  add("profile", "verified", membership.participantId);
  add("service", "verified", binding.service_instance_ref);
  add("client", "verified", binding.reasoning_binding_id);
  add("binding", "verified", binding.reasoning_binding_id);
  try {
    const environments = await dependencies2.environments(room);
    const environment = environments.find((row) => row.environment_binding_id === input.environmentBindingId);
    const exact = environment && environment.room_id === room.roomId && environment.source_id === input.sourceId && environment.world_id === input.worldId;
    if (!exact) {
      add("source", "blocked", input.environmentBindingId, ["session_source_identity_mismatch"]);
      add("subject", "blocked", input.subjectBindingId, ["session_source_identity_mismatch"]);
    } else {
      try {
        const devices = await dependencies2.devices({ ownerProfileId: room.profileId, roomId: room.roomId });
        const exactDevices = devices.filter((row) => row.environment_binding_id === input.environmentBindingId && row.room_id === room.roomId && row.source_id === input.sourceId && row.world_id === input.worldId);
        const device = exactDevices.length === 1 ? exactDevices[0] : null;
        const deadline = device?.credential_expires_at ? Date.parse(device.credential_expires_at) : NaN;
        if (!device) {
          add("source", "blocked", input.environmentBindingId, ["session_source_credential_identity_unverified"]);
        } else if (device.credential_status !== "active" || !Number.isFinite(deadline)) {
          add(
            "source",
            device.credential_status === "revoked" ? "revoked" : "blocked",
            input.sourceId,
            [device.credential_status !== "active" ? "session_source_credential_inactive" : "session_source_credential_deadline_unavailable"]
          );
        } else add(
          "source",
          environment.connection_status === "active" && environment.subject_directory?.freshness === "fresh" ? "verified" : environment.connection_status === "revoked" ? "revoked" : "stale",
          environment.source_id,
          environment.connection_status !== "active" ? ["session_source_not_active"] : environment.subject_directory?.freshness !== "fresh" ? ["session_source_not_fresh"] : [],
          deadline
        );
      } catch (error) {
        failure("source", error);
      }
      const subject = environment.self_subject_binding;
      const subjectExact = subject?.subject_binding_id === input.subjectBindingId && subject.participant_id === membership.participantId && subject.room_id === room.roomId && subject.environment_binding_id === input.environmentBindingId && subject.source_id === input.sourceId && subject.world_id === input.worldId;
      if (subjectExact && subject.status === "active") {
        try {
          const verified = await dependencies2.subject({
            ...room,
            environmentBindingId: input.environmentBindingId,
            subjectRef: subject.subject_ref
          });
          add(
            "subject",
            verified.subject_binding_id === input.subjectBindingId ? "verified" : "stale",
            input.subjectBindingId,
            verified.subject_binding_id === input.subjectBindingId ? [] : ["session_subject_changed_during_read"],
            verified.expires_at ? Date.parse(verified.expires_at) : null
          );
        } catch (error) {
          failure("subject", error);
        }
      } else add(
        "subject",
        !subjectExact ? "missing" : subject.status === "revoked" ? "revoked" : "stale",
        input.subjectBindingId,
        !subjectExact ? ["session_subject_identity_mismatch"] : ["session_subject_stale"],
        subjectExact && subject.expires_at ? Date.parse(subject.expires_at) : null
      );
    }
  } catch (error) {
    failure("source", error);
    failure("subject", error);
  }
  const environmentInput = { ...room, environmentBindingId: input.environmentBindingId };
  try {
    const authorities2 = await dependencies2.authorities(environmentInput);
    const authority7 = authorities2.find((row) => row.action_authority_id === input.actionAuthorityId);
    const exact = authority7 && authority7.environment_binding_id === input.environmentBindingId && authority7.room_id === room.roomId && authority7.source_id === input.sourceId && authority7.world_id === input.worldId && authority7.participant_id === membership.participantId && authority7.subject_binding_id === input.subjectBindingId;
    const newGrantRequired = Boolean(exact && environmentActionAuthorityRequiresNewGrant(authority7));
    add(
      "authority",
      !exact ? "missing" : authority7.status === "active" && authority7.expires_at ? "verified" : authority7.status === "revoked" ? "revoked" : "blocked",
      input.actionAuthorityId,
      !exact ? ["session_authority_identity_mismatch"] : newGrantRequired ? ["session_authority_new_grant_required"] : !authority7.expires_at ? ["session_finite_authority_required"] : authority7.status === "active" ? [] : ["session_authority_inactive"],
      exact && authority7.expires_at ? Date.parse(authority7.expires_at) : null,
      newGrantRequired
    );
  } catch (error) {
    failure("authority", error);
  }
  try {
    const controllers = await dependencies2.controllers(environmentInput);
    const controller = controllers.find((row) => row.action_authority_id === input.actionAuthorityId);
    const heartbeatAt = controller?.heartbeat_received_at ? Date.parse(controller.heartbeat_received_at) : NaN;
    const current = controller?.ready_for_actions && Number.isFinite(heartbeatAt) && heartbeatAt <= Date.now();
    add(
      "controller",
      current ? "verified" : "blocked",
      input.actionAuthorityId,
      current ? [] : ["session_controller_not_ready"],
      controller?.heartbeat_received_at ? Date.parse(controller.heartbeat_received_at) + controller.heartbeat_max_age_ms : null
    );
  } catch (error) {
    failure("controller", error);
  }
  try {
    const goal = await dependencies2.goal(input.context);
    const exact = goal.goal_id === input.context.goalId && goal.goal_revision === input.context.expectedRevision && goal.identity.run_id === input.context.runId && goal.identity.room_id === room.roomId && goal.identity.environment_binding_id === input.environmentBindingId && goal.identity.source_id === input.sourceId && goal.identity.world_id === input.worldId && goal.identity.subject_binding_id === input.subjectBindingId && goal.identity.action_authority_id === input.actionAuthorityId;
    add(
      "goal",
      exact ? "verified" : "stale",
      goal.goal_id,
      exact ? [] : ["session_goal_identity_mismatch"]
    );
  } catch (error) {
    failure("goal", error);
  }
  try {
    const evidence = await dependencies2.perception(input, bindingStore);
    add("perception", "verified", evidence.context.evidence.observation.evidence_ref);
  } catch (error) {
    failure("perception", error);
  }
  await bindingStore.verifyTaskAssociation(input.binding);
  return projectEnvironmentSessionReadiness({
    context_ref: contextRef,
    checks,
    now_ms: Date.now(),
    maximum_check_age_ms: 5e3
  });
}

// server/services/environment-connectors/session/recover-session-goal.ts
var services = {
  goals: environmentDurableGoalStore,
  database: readSharedRealtimeRoomDatabase,
  identity: resolveCurrentEnvironmentDurableGoalIdentity,
  perception: readExactEnvironmentPerceptionEvidence
};
async function recoverEnvironmentSessionGoal(input, bindingStore, dependencies2 = services) {
  const fail = () => new EnvironmentDurableGoalError(
    "durable_goal_identity_mismatch",
    409,
    "Ready up requires the exact existing task, run, environment and player."
  );
  if (!input.context.runId || input.context.runId !== input.binding.runId || input.context.profileId !== input.binding.profileRef) throw fail();
  await bindingStore.verifyTaskAssociation(input.binding);
  let goal = await dependencies2.goals.inspect(input.context);
  const prior = goal.identity;
  if (prior.run_id !== input.context.runId || prior.room_id !== input.context.roomId || prior.environment_binding_id !== input.environmentBindingId || prior.source_id !== input.sourceId || prior.world_id !== input.worldId || prior.subject_binding_id !== input.subjectBindingId) throw fail();
  if (goal.status === "active" && !goal.recovery.required) {
    await dependencies2.goals.resolveTemporalAdmissionContext({ ...input.context, expectedRevision: goal.revision });
    await bindingStore.verifyTaskAssociation(input.binding);
    return {
      goal,
      changed: false,
      execution_authority: false,
      answer_authority: false,
      terminal_eligible: false
    };
  }
  if (goal.status !== "recovery_required" || !goal.recovery.required || !["disconnect", "fabric_restart", "helix_restart", "connector_epoch_changed"].includes(goal.recovery.reason ?? "")) {
    throw new EnvironmentDurableGoalError(
      "durable_goal_authority_stale",
      409,
      "This recovery reason requires explicit operator intent; Ready up will not resume it."
    );
  }
  const request = {
    ownerProfileId: input.context.profileId,
    roomId: input.context.roomId,
    participantId: input.context.participantId,
    environmentBindingId: input.environmentBindingId,
    subjectNativeId: prior.subject_native_id,
    actionAuthorityId: input.actionAuthorityId,
    runId: input.context.runId,
    turnId: input.context.turnId
  };
  const identity = await dependencies2.identity(await dependencies2.database(), {
    ...request,
    ownerProfileId: prior.owner_profile_id,
    goalOwnerParticipantId: prior.goal_owner_participant_id,
    authorityParticipantId: prior.authority_participant_id
  });
  if (identity.subject_binding_id !== input.subjectBindingId || identity.source_id !== input.sourceId || identity.world_id !== input.worldId || identity.environment_binding_id !== input.environmentBindingId || identity.subject_native_id !== prior.subject_native_id) throw fail();
  const readEvidence = () => dependencies2.perception({
    identity,
    probeRequestId: input.context.probeRequestId,
    priorTurnId: input.context.priorTurnId
  });
  const { evidence } = await readEvidence();
  const revision = evidence.observation.result.observation_revision;
  if (typeof revision !== "number" || !Number.isSafeInteger(revision) || revision < 0) throw new EnvironmentDurableGoalError(
    "durable_goal_evidence_identity_mismatch",
    409,
    "Recovery requires an exact observation revision."
  );
  const refs = [evidence.observation.evidence_ref];
  const append = async (payload18) => {
    const fresh = await readEvidence();
    if (fresh.evidence.observation.evidence_ref !== refs[0] || fresh.evidence.observation.result.observation_revision !== revision) throw fail();
    await bindingStore.verifyTaskAssociation(input.binding);
    goal = await dependencies2.goals.append({
      ...request,
      goalId: goal.goal_id,
      expectedRevision: goal.revision,
      payload: payload18,
      evidenceRefs: refs
    });
  };
  if (!goal.recovery.rebound_event_id) await append({
    kind: "authority_rebound",
    superseded_producer_epoch_ref: prior.producer_epoch_ref,
    fresh_observation_revision: revision
  });
  const facts2 = {
    environment_binding_id: identity.environment_binding_id,
    subject_binding_id: identity.subject_binding_id,
    source_id: identity.source_id,
    observation_revision: revision
  };
  const checkpointId = `checkpoint:ready-up:${helixEnvironmentDurableGoalSha256({
    goal_id: goal.goal_id,
    rebound_event_id: goal.recovery.rebound_event_id,
    evidence_refs: refs
  })}`;
  if (goal.latest_checkpoint?.checkpoint_id !== checkpointId) await append({
    kind: "checkpoint_verified",
    checkpoint_id: checkpointId,
    milestone_id: null,
    observation_revision: revision,
    verified_facts: facts2,
    completed_postcondition_ids: [],
    incomplete_postcondition_ids: [],
    checkpoint_evidence_hash: helixEnvironmentDurableGoalSha256({
      evidence_refs: refs,
      observation_revision: revision,
      verified_facts: facts2,
      completed_postcondition_ids: [],
      incomplete_postcondition_ids: []
    })
  });
  await append({ kind: "goal_resumed", recovery_checkpoint_id: checkpointId });
  await bindingStore.verifyTaskAssociation(input.binding);
  return {
    goal,
    changed: true,
    execution_authority: false,
    answer_authority: false,
    terminal_eligible: false
  };
}

// server/services/environment-connectors/session/ready-up-session.ts
var services2 = {
  inspect: readEnvironmentSessionReadiness,
  environments: listRoomEnvironmentProjections,
  refreshSubject: refreshOwnRoomEnvironmentSubjectEpoch,
  recoverGoal: recoverEnvironmentSessionGoal
};
async function readyUpEnvironmentSession(input, bindingStore, dependencies2 = services2) {
  const before = await dependencies2.inspect(input, bindingStore);
  const repairs = [];
  const subject = before.checks.find((check) => check.layer === "subject");
  const source = before.checks.find((check) => check.layer === "source");
  if (subject?.state === "stale" && source?.state === "verified") {
    const environments = await dependencies2.environments({
      profileId: input.context.profileId,
      roomId: input.context.roomId
    });
    const selected = environments.find((environment) => environment.environment_binding_id === input.environmentBindingId && environment.room_id === input.context.roomId && environment.source_id === input.sourceId && environment.world_id === input.worldId);
    const prior = selected?.self_subject_binding;
    if (prior && prior.subject_binding_id === input.subjectBindingId && prior.participant_id === input.context.participantId && prior.status !== "revoked") {
      await bindingStore.verifyTaskAssociation(input.binding);
      try {
        const refreshed = await dependencies2.refreshSubject({
          roomId: input.context.roomId,
          profileId: input.context.profileId,
          environmentBindingId: input.environmentBindingId,
          subjectRef: prior.subject_ref,
          subjectBindingId: prior.subject_binding_id,
          expectedProducerEpochRef: prior.producer_epoch_ref
        });
        repairs.push({
          layer: "subject",
          changed: refreshed.producer_epoch_ref !== prior.producer_epoch_ref,
          reason_code: "subject_epoch_checked"
        });
      } catch (error) {
        if (!(error instanceof RoomEnvironmentSubjectError)) throw error;
        repairs.push({ layer: "subject", changed: false, reason_code: error.code });
      }
    }
  }
  let readiness = await dependencies2.inspect(input, bindingStore);
  if (readiness.checks.some((check) => check.layer === "goal" && check.state !== "verified") && ["source", "subject", "authority", "controller"].every((layer) => readiness.checks.some((check) => check.layer === layer && check.state === "verified"))) {
    try {
      const recovered = await dependencies2.recoverGoal(input, bindingStore);
      repairs.push({ layer: "goal", changed: recovered.changed, reason_code: "goal_recovery_checked" });
      readiness = await dependencies2.inspect({
        ...input,
        context: { ...input.context, expectedRevision: recovered.goal.revision }
      }, bindingStore);
    } catch (error) {
      if (!isEnvironmentDurableGoalError(error)) throw error;
      repairs.push({ layer: "goal", changed: null, reason_code: error.code });
      readiness = await dependencies2.inspect(input, bindingStore);
    }
  }
  return {
    schema: "helix.environment_session_ready_up.v1",
    selection: { room_id: input.context.roomId, environment_binding_id: input.environmentBindingId },
    readiness,
    repairs,
    execution_authority: false,
    answer_authority: false,
    assistant_answer: false,
    terminal_eligible: false
  };
}

// server/services/environment-connectors/session/prepare-browser-session.ts
var import_node_crypto56 = require("node:crypto");

// server/services/local-supervisor/reasoning-run-association.ts
var resolveReasoningRunAssociation = async (presence) => {
  const runtime = presence.verified_retained_runtime_identity;
  const room = presence.verified_room_identity;
  const now = Date.now();
  if (!presence.active || !runtime || !room || runtime.basis !== "server_verified" || room.basis !== "server_verified" || !(Date.parse(presence.observed_at) <= now) || !(Date.parse(presence.heartbeat_expires_at) > now) || presence.run_ref !== runtime.run_ref || presence.room_ref !== room.room_ref) return null;
  await ensureDatabase();
  const { rows } = await getPool().query(
    `SELECT r.run_id, r.expires_at
       FROM helix_agent_runs r
       JOIN helix_agent_run_room_bindings b ON b.run_id = r.run_id
        AND b.tenant_id = r.tenant_id AND b.issuer = r.issuer
        AND b.subject_id = r.subject_id AND b.account_profile_id = r.account_profile_id
      WHERE r.run_id = $1 AND r.account_profile_id = $2 AND r.version = $3
        AND r.lifecycle_status IN ('queued', 'running', 'waiting')
        AND r.expires_at > NOW() AND r.cancelled_at IS NULL
        AND r.completed_at IS NULL AND r.steps_used < r.max_steps
        AND b.binding_id = $4 AND b.version = $5 AND b.status = 'active'
        AND b.room_id = $6 AND b.participant_id_at_bind = $7
      LIMIT 1`,
    [
      runtime.run_ref,
      presence.authenticated_profile_ref,
      runtime.run_version,
      runtime.run_room_binding_ref,
      runtime.run_room_binding_version,
      room.room_ref,
      room.participant_ref
    ]
  );
  if (!rows.length) return null;
  const expires = new Date(rows[0].expires_at).getTime();
  if (!Number.isFinite(expires) || expires <= Date.now()) return null;
  return {
    run_id: runtime.run_ref,
    run_version: runtime.run_version,
    room_id: room.room_ref,
    room_binding_id: runtime.run_room_binding_ref,
    room_binding_version: runtime.run_room_binding_version,
    verification_ref: runtime.verification_ref,
    run_expires_at: new Date(expires).toISOString()
  };
};

// server/services/helix-ask/runtime/external-capability-policy.ts
var import_node_async_hooks = require("node:async_hooks");
