var rng = (start2, stop, step) => {
  const out = [];
  if (step === 0) return out;
  const dir = step > 0 ? 1 : -1;
  for (let x = start2; dir > 0 ? x <= stop + 1e-12 : x >= stop - 1e-12; x += step) {
    out.push(Number(x.toFixed(9)));
  }
  return out;
};
