    primaryOrigin: options?.primaryOrigin ?? originFamilies[0],
    originSummary,
    observableRoutes: options?.observableRoutes,
    evidenceNotes: options?.evidenceNotes ?? [defaultEvidenceNote(originSummary)],
    sourceKeys: options?.sourceKeys
